<template>
  <main class="paper-shell"><div class="paper-container tool-container"><header class="paper-workspace-header"><div><div class="paper-page-eyebrow">Knowledge Base / Compare</div><h1 class="paper-page-title">Cross-paper metric comparison</h1><p class="paper-page-description">Browse extracted metrics or compare one reported measure across papers.</p></div></header><LiteratureKnowledgeNav />
    <form class="paper-panel compare-form" @submit.prevent="compare"><input v-model="metric" placeholder="Metric name, e.g. yield / efficiency / reduction" /><button class="paper-button primary" :disabled="pending">Compare</button></form><p v-if="error" class="notice">{{ error }}</p>
    <section class="paper-panel results"><div class="section-heading"><strong>{{ metric.trim() ? `Results for “${metric}”` : 'Available metrics' }}</strong><span>{{ metric.trim() ? results.length : metrics.length }} records</span></div>
      <div v-if="!metric.trim()" class="metric-grid"><button v-for="item in metrics" :key="item.metric_name" @click="choose(item.metric_name)"><strong>{{ item.metric_name }}</strong><span>{{ item.count }} data points · {{ item.paper_count }} papers</span><small v-if="item.year_min">{{ item.year_min === item.year_max ? item.year_min : `${item.year_min}–${item.year_max}` }}</small><small v-if="item.sample != null" class="metric-sample">Sample: {{ item.sample }}{{ item.unit ? ` ${item.unit}` : '' }}</small></button></div>
      <template v-else-if="results.length"><div ref="chart" class="compare-chart"></div><table><thead><tr><th>Paper</th><th>Metric</th><th>Value</th><th>Unit</th><th>Context</th></tr></thead><tbody><tr v-for="(row,index) in results" :key="`${row.paper_id}-${index}`" @click="router.push(`/literature/${row.paper_id}`)"><td>{{ row.title||`Paper ${row.paper_id}` }}</td><td>{{ row.metric_name }}</td><td>{{ row.metric_value }}</td><td>{{ row.unit||'—' }}</td><td>{{ row.context||'—' }}</td></tr></tbody></table></template><div v-else class="empty">{{ pending?'Loading…':'No matching metric data.' }}</div>
    </section></div></main>
</template>
<script setup>
import '~/assets/paper-platform.css';import LiteratureKnowledgeNav from '~/components/LiteratureKnowledgeNav.vue'
const config=useRuntimeConfig(),router=useRouter(),route=useRoute(),chart=ref(null),metric=ref(String(route.query.metric||'')),pending=ref(false),error=ref(''),results=ref([]),points=ref([]);useHead({title:'Compare Literature Metrics - OpenIsle'})
const metrics=computed(()=>{const map=new Map();for(const p of points.value){if(!p.metric_name)continue;const x=map.get(p.metric_name)||{metric_name:p.metric_name,count:0,papers:new Set(),year_min:null,year_max:null,sample:p.metric_value??null,unit:p.unit||''};x.count++;if(p.paper_id!=null)x.papers.add(p.paper_id);if(p.year){x.year_min=x.year_min==null?p.year:Math.min(x.year_min,p.year);x.year_max=x.year_max==null?p.year:Math.max(x.year_max,p.year)}map.set(p.metric_name,x)}return [...map.values()].map(x=>({...x,paper_count:x.papers.size})).sort((a,b)=>b.count-a.count)})
const ensureCharts=async()=>{if(window.OpenIsleLiteratureCharts)return window.OpenIsleLiteratureCharts;window.Utils=window.Utils||{truncate:(v,n)=>String(v||'').slice(0,n),escapeHtml:v=>String(v||'')};window.I18n=window.I18n||{t:k=>k};await new Promise((ok,bad)=>{const s=document.createElement('script');s.src='/literature-engine/charts.js';s.onload=ok;s.onerror=bad;document.head.appendChild(s)});return window.OpenIsleLiteratureCharts}
const compare=async()=>{if(!metric.value.trim())return;pending.value=true;error.value='';try{const p=new URLSearchParams({metric_name:metric.value.trim(),top_k:'30'});const data=await $fetch(`${config.public.apiBaseUrl}/api/literature/explore/compare/metric?${p}`);results.value=data.results||[];await router.replace({query:{metric:metric.value.trim()}});await nextTick();const numeric=results.value.filter(row=>Number.isFinite(Number(row.metric_value))).map(row=>({label:String(row.title||`Paper ${row.paper_id}`).slice(0,36),value:Number(row.metric_value)}));if(numeric.length){const c=await ensureCharts();c.barChart(chart.value,numeric,{height:Math.max(280,numeric.length*34)})}}catch(cause){error.value=cause?.data?.message||cause?.message||'Comparison failed.'}finally{pending.value=false}};const choose=name=>{metric.value=name;compare()}
onMounted(async()=>{try{const data=await $fetch(`${config.public.apiBaseUrl}/api/literature/explore/data_points/list?limit=500&offset=0`);points.value=data.data_points||[];if(metric.value.trim())await compare()}catch(cause){error.value=cause?.message||'Unable to load metrics.'}})
</script>
<style scoped>
.tool-container{max-width:1180px}.compare-form{display:grid;grid-template-columns:1fr auto;gap:10px;padding:15px;margin-bottom:16px}.compare-form input{border:1px solid var(--paper-line);padding:10px 12px}.results{overflow:hidden}.section-heading{display:flex;justify-content:space-between;padding:14px 18px;border-bottom:1px solid var(--paper-line)}.section-heading span{color:var(--paper-muted);font-size:11px}.metric-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:1px;background:var(--paper-line)}.metric-grid button{display:grid;gap:5px;border:0;padding:15px;background:#fff;color:var(--paper-ink);text-align:left;cursor:pointer}.metric-grid button:hover{background:#f4f9fa}.metric-grid span,.metric-grid small{color:var(--paper-muted);font-size:11px}.metric-grid .metric-sample{color:var(--paper-teal);font-weight:700}.compare-chart{min-height:280px;padding:16px;border-bottom:1px solid var(--paper-line)}.results table{width:100%;border-collapse:collapse}.results th,.results td{padding:11px 14px;border-bottom:1px solid var(--paper-line);text-align:left;font-size:12px}.results th{color:var(--paper-muted);font-size:10px;text-transform:uppercase}.results tbody tr{cursor:pointer}.empty{padding:50px;text-align:center;color:var(--paper-muted)}.notice{padding:10px 14px;background:#fff4f2;color:#8b3028}
</style>
